//go:build transcodechaos

package plex

import (
	"context"
	"fmt"
	"io"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/braedonsaunders/ether/internal/config"
	"github.com/braedonsaunders/ether/internal/transcode"
)

// The corpus is generated by cmd/transcodechaos -corpus; .good provides
// the source facts and .media is what the encoder actually reads.
func TestTranscodeChaosMatrix(t *testing.T) {
	corpus, ff, fp := os.Getenv("CHAOS_CORPUS"), os.Getenv("CHAOS_FFMPEG"), os.Getenv("CHAOS_FFPROBE")
	if corpus == "" {
		t.Skip("set CHAOS_CORPUS to run the generated input matrix")
	}
	if ff == "" || fp == "" {
		t.Fatal("set CHAOS_FFMPEG and CHAOS_FFPROBE")
	}
	entries, err := filepath.Glob(filepath.Join(corpus, "*.good"))
	if err != nil || len(entries) == 0 {
		t.Fatal("corpus has no input fixtures")
	}
	source := httptest.NewServer(http.FileServer(http.Dir(corpus)))
	defer source.Close()
	m, err := transcode.New(config.Transcode{FFmpegPath: ff, FFprobePath: fp, HWAccel: "none", TempDir: filepath.Join(t.TempDir(), "work")}, slog.New(slog.NewTextHandler(io.Discard, nil)), transcode.WithSegmentTimeout(10*time.Second))
	if err != nil {
		t.Fatal(err)
	}
	defer m.Close()
	check := func(t *testing.T, b []byte, ext string) {
		t.Helper()
		if len(b) == 0 {
			t.Fatal("empty output")
		}
		p := filepath.Join(t.TempDir(), "media."+ext)
		if e := os.WriteFile(p, b, 0600); e != nil {
			t.Fatal(e)
		}
		if saved := os.Getenv("CHAOS_SAVE_MEDIA"); saved != "" {
			if e := os.WriteFile(saved, b, 0600); e != nil {
				t.Fatal(e)
			}
		}
		chaosCmd(t, fp, "-v", "error", "-show_streams", p)
		chaosCmd(t, ff, "-v", "error", "-xerror", "-i", p, "-f", "null", "-")
	}
	for _, entry := range entries {
		name := strings.TrimSuffix(filepath.Base(entry), ".good")
		t.Run(name, func(t *testing.T) {
			info, err := m.Probe(context.Background(), source.URL+"/"+name+".good")
			if err != nil {
				t.Fatalf("probe: %v", err)
			}
			info.Keyframes = nil
			for _, path := range []string{"hls", "dash", "start-mkv", "download"} {
				t.Run(path, func(t *testing.T) {
					if path == "download" && name == "input-hevc10-hdr" {
						t.Skip("HDR source is not an eligible copy-only download")
					}
					inputURL := source.URL + "/" + name + ".media"
					if path == "download" {
						f := newDownloadFixture(t, true)
						f.playback.info = *info
						f.srv.d.Playback = &chaosPlayback{f.playback, inputURL}
						dl, e := m.NewDownloadRemuxer(config.Downloads{})
						if e != nil {
							t.Fatal(e)
						}
						f.srv.d.Downloads = dl
						q := f.queue(t)
						r := f.do(t, http.MethodPost, "/downloadQueue/"+itoa(q)+"/add?keys=/library/metadata/"+fightClub.Key.String(), ownerToken, nil)
						if r.Code != 200 {
							t.Fatalf("add HTTP %d", r.Code)
						}
						deadline := time.Now().Add(8 * time.Second)
						var item map[string]any
						for time.Now().Before(deadline) {
							items := f.items(t, q)
							if len(items) == 1 {
								item = items[0]
								if item["status"] == downloadAvailable {
									break
								}
								if item["status"] == downloadError {
									t.Fatalf("download conversion failed")
								}
							}
							time.Sleep(50 * time.Millisecond)
						}
						if item == nil || item["status"] != downloadAvailable {
							t.Fatal("download timed out")
						}
						id := int64(item["id"].(float64))
						r = f.do(t, http.MethodGet, "/downloadQueue/"+itoa(q)+"/item/"+itoa(id)+"/media", ownerToken, nil)
						if r.Code != 200 {
							t.Fatalf("media HTTP %d", r.Code)
						}
						check(t, r.Body.Bytes(), "mp4")
						f.do(t, http.MethodDelete, "/downloadQueue/"+itoa(q)+"/items/"+itoa(id), ownerToken, nil)
						return
					}
					f := newFixture()
					defer f.srv.Close()
					f.playback.info = *info
					f.srv.d.Playback = &chaosPlayback{f.playback, inputURL}
					f.srv.d.Transcoder = m
					id := "matrix-" + path
					query := "path=%2Flibrary%2Fmetadata%2F" + fightClub.Key.String() + "&session=" + id + "&directPlay=0&directStream=1"
					if strings.Contains(name, "subtitle") || strings.Contains(name, "broken-") {
						for _, st := range info.Streams {
							if st.Type == "subtitle" {
								track := f.bindStream(fightClub.Key, st.Index, st)
								query += fmt.Sprintf("&subtitles=burn&subtitleStreamID=%d", track)
								break
							}
						}
					}
					get := func(p string) []byte {
						t.Helper()
						r := f.get(t, p, "X-Plex-Product", "Plex Web", "X-Plex-Platform", "Chrome")
						if r.Code != 200 {
							t.Fatalf("HTTP %d for %s", r.Code, p)
						}
						return r.Body.Bytes()
					}
					defer func() {
						f.get(t, "/video/:/transcode/universal/stop?session="+id, "X-Plex-Product", "Plex Web", "X-Plex-Platform", "Chrome")
					}()
					switch path {
					case "hls":
						get("/video/:/transcode/universal/start.m3u8?" + query + "&protocol=hls")
						for n := 0; n < 3 && (info.Duration <= 0 || time.Duration(n)*4*time.Second < info.Duration); n++ {
							check(t, get(fmt.Sprintf("/video/:/transcode/universal/session/%s/base/%05d.ts", id, n)), "ts")
						}
					case "dash":
						get("/video/:/transcode/universal/start.mpd?" + query + "&protocol=dash")
						base := "/video/:/transcode/universal/session/" + id + "/0/"
						init := get(base + "header")
						for n := 0; n < 2 && (info.Duration <= 0 || time.Duration(n)*5*time.Second < info.Duration); n++ {
							media := get(fmt.Sprintf("%s%d.m4s", base, n))
							check(t, append(append([]byte(nil), init...), media...), "mp4")
						}
					case "start-mkv":
						check(t, get("/video/:/transcode/universal/start.mkv?"+query+"&protocol=http"), "mkv")
					}
				})
			}
		})
	}
}
